package com.sirithree.shopops.admin.benchmark.v1.dataset.stage7b; import static org.assertj.core.api.Assertions.assertThat; import org.junit.jupiter.api.Test; import java.util.*;
class GovernanceScaleupPositiveValidityTest { @Test void everyNewPositiveIsFullyLegitimateOutsideTargetPolicy() throws Exception { Map<String,Object>d=Stage7BGovernanceDatasetSupport.objectResource("/benchmark/v1/governance/scaleup/governance-root-blueprints.json"); @SuppressWarnings("unchecked") List<Map<String,Object>> roots=(List<Map<String,Object>>)d.get("roots"); var p=roots.stream().filter(x->"ACCEPTED".equals(x.get("feasibilityStatus"))&&"POSITIVE".equals(x.get("caseClass"))).toList(); assertThat(p).hasSize(25); assertThat(p).allSatisfy(x->assertThat(x.get("allNonTargetPoliciesValid")).isEqualTo(true)); }}
